function BX_url() { return 'https://www.banxia.tw/'; }
function BX_web() { return 'document.documentElement.outerHTML'; }
function BX_check() {
  java.toast('正在检测访问状态，请稍候约 6 秒…');
  var s = '';
  try { s = String(java.webViewGetSource('', BX_url(), BX_web(), '', false, 5000)); } catch (e) {}
  if (s.indexOf('altcha-widget') >= 0) {
    java.toast('⛔ 仍被验证页拦截，请点「打开网站」在浏览器过盾');
  } else if (s.indexOf('半夏') >= 0 && s.length > 3000) {
    java.toast('✅ 访问正常，可搜索阅读');
  } else {
    java.toast('⚠️ 返回异常（' + s.length + '字符），请重试或点「打开网站」');
  }
}
function BX_pass() { BX_check(); }
function BX_open() {
  java.toast('正在打开网站，如出现「我不是机器人」请点一下');
  try { java.startBrowser(BX_url(), '半夏小说'); } catch (e) { java.toast('打开失败：' + String(e)); }
}
